const COLOR = "#FFF1B5";

// product & design strategy: soft radial pulse — a thin ring expands out
// from the dot and fades in alongside a light scale on the dot itself.
// Both restore smoothly together on mouse leave/blur since they're plain
// two-state transitions, not a one-shot keyframe animation.
export default function StrategyIcon() {
  return (
    <AnimatedIcon>
      <path fill="#f4f4f4" fillOpacity=".05" d={BADGE_D} />
      <circle
        cx="7.52513"
        cy="7.52513"
        r="4"
        fill="none"
        stroke={COLOR}
        strokeWidth="1"
        className={`origin-center scale-[0.6] opacity-0 transition-[transform,opacity] ${ICON_DURATION} ${EASE_SMOOTH} ${MOTION_REDUCE} group-hover:scale-[1.9] group-hover:opacity-35 group-focus:scale-[1.9] group-focus:opacity-35`}
        style={FILL_BOX}
      />
      <g
        fill={COLOR}
        className={`origin-center transition-transform ${ICON_DURATION} ${EASE_POP} ${MOTION_REDUCE} group-hover:scale-[1.1] group-focus:scale-[1.1]`}
        style={FILL_BOX}
      >
        <path d={DOT_D} />
        <path d={TEXTURE_D} />
      </g>
    </AnimatedIcon>
  );
}
